//! The Effects store's locked-in sets: the objects one continuous effect affects when it
//! affects several (the crate's contract, "Stores").
//!
//! [CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c): "If a continuous effect
//! generated by the resolution of a spell or ability modifies the characteristics or changes
//! the controller of any objects, the set of objects it affects is determined when that
//! continuous effect begins. After that point, the set won't change."
//!
//! A set of slots is 32 bytes in [`Small`], more than an entry, so the sets are a table of
//! their own and an entry names its set by index ([`LockedIn`]). An empty set is a free
//! place in the table: the effect whose set it was has ended. The table has no empty set
//! at its end, so a store with no set live has an empty table, whatever it once held.

use crate::bitboard::Bitboard;
use crate::fit::{Misfit, room};
use crate::fixed::Full;
use crate::layout::{Layout, Queue, Small, index};
use crate::relayout::bits;
use crate::state::{State, Zone};
use crate::store::Duration;

use super::{Affects, ContinuousEffect, Kinds, LayerChange, Payload};

/// The sets of objects a [`Small`] game's effects hold locked in at once. One past it
/// stalls the game into [`crate::Large`], whose table grows.
pub const SETS: usize = 4;

/// The name of a locked-in set: its place in the store's table. Only the store makes one,
/// as an effect on several objects begins ([`State::start_effect_on_set`]), and
/// [`State::locked_in`] reads its members.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct LockedIn<L: Layout = Small>(L::Index);

impl<L: Layout> LockedIn<L> {
    #[inline]
    fn index(self) -> usize {
        self.0.into()
    }

    /// The set at the same place of a table in layout `M`.
    pub(super) fn relayout<M: Layout>(self) -> LockedIn<M> {
        LockedIn(index::<M>(self.index()))
    }
}

/// The table of locked-in sets.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct Sets<L: Layout>(L::Queue<Bitboard<L::Slot>, SETS>);

impl Copy for Sets<Small> {}

impl<L: Layout> Sets<L> {
    pub(super) fn empty() -> Self {
        Sets(Default::default())
    }

    /// The members of `set` that are still the objects they were; none once its effect has
    /// ended.
    #[inline]
    pub(super) fn members(&self, set: LockedIn<L>) -> Bitboard<L::Slot> {
        (self.0.as_slice().get(set.index()).copied()).unwrap_or(Bitboard::EMPTY)
    }

    /// Every member of every set.
    pub(super) fn all(&self) -> Bitboard<L::Slot> {
        self.0.iter().fold(Bitboard::EMPTY, |all, &set| all | set)
    }

    /// The sets in use.
    pub(super) fn live(&self) -> usize {
        self.0.iter().filter(|set| !set.is_empty()).count()
    }

    /// Whether the table is as short as its sets allow: its last set is in use.
    pub(super) fn is_trimmed(&self) -> bool {
        self.0.as_slice().last().is_none_or(|set| !set.is_empty())
    }

    /// Keeps `members` in the first free place of the table.
    fn lock_in(&mut self, members: Bitboard<L::Slot>) -> Result<LockedIn<L>, Full> {
        let place = if let Some(free) = self.0.iter().position(|set| set.is_empty()) {
            self.0.as_mut_slice()[free] = members;
            free
        } else {
            self.0.push(members)?;
            self.0.len() - 1
        };
        Ok(LockedIn(index::<L>(place)))
    }

    /// Frees `set`'s place: its effect has ended. [`Sets::trim`] follows the last of them.
    #[inline]
    pub(super) fn release(&mut self, set: LockedIn<L>) {
        self.0.as_mut_slice()[set.index()] = Bitboard::EMPTY;
    }

    /// Drops the free places at the end of the table.
    #[inline]
    pub(super) fn trim(&mut self) {
        while self.0.as_slice().last().is_some_and(|set| set.is_empty()) {
            self.0.pop();
        }
    }

    /// The object in `slot` has ended, so it is a member of no set
    /// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)): whatever arrives in
    /// the slot is "a new object with no memory of, or relation to, its previous existence."
    /// Says whether it was one.
    pub(super) fn leave(&mut self, slot: L::Slot) -> bool {
        let mut left = false;
        for set in self.0.as_mut_slice() {
            left |= set.contains(slot);
            set.remove(slot);
        }
        left
    }

    /// Whether layout `M`'s table has a place for each of the sets'.
    pub(super) fn fits<M: Layout>(&self) -> Result<(), Misfit> {
        room(
            "the locked-in sets",
            self.0.len(),
            <M::Queue<Bitboard<M::Slot>, SETS> as Queue<_>>::CAPACITY,
        )
    }

    /// The table in layout `M`: each set at its place, its members at theirs.
    pub(super) fn relayout<M: Layout>(&self) -> Sets<M> {
        Sets(crate::relayout::queue(self.0.as_slice(), |&set| bits(set)))
    }
}

impl<L: Layout> State<L> {
    /// Starts one continuous effect of the card `source` that changes each of `members` in
    /// a layer, with one timestamp
    /// ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "the set of objects
    /// it affects is determined when that continuous effect begins. After that point, the set
    /// won't change."
    /// [CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137): an effect's timestamp
    /// is the time it was created, so the members share it. The members are permanents, the
    /// objects of the battlefield as they are now. One that leaves is no longer affected
    /// and the rest still are; the effect ends with the last of them.
    ///
    /// An effect on one object is an entry on that object ([`State::start_effect`]): the
    /// same effect, and the table's places stay for the effects that need one. An effect on
    /// none never begins.
    #[inline]
    pub fn start_effect_on_set(
        &mut self,
        source: L::Card,
        members: Bitboard<L::Slot>,
        change: LayerChange,
        duration: Duration,
    ) -> Result<(), Full> {
        let payload = Payload::Layer(change);
        let mut rest = members.iter();
        match (rest.next(), rest.next()) {
            (None, _) => Ok(()),
            (Some(sole), None) => {
                let object = Affects::object(self.object_ref(sole));
                self.start_effect(source, object, payload, duration)
            }
            _ => self.lock_in(source, members, payload, duration),
        }
    }

    /// The path of [`State::start_effect_on_set`] for two members or more, out of line:
    /// what a game does when it has such an effect, and none of the cost of one that has
    /// not.
    #[inline(never)]
    fn lock_in(
        &mut self,
        source: L::Card,
        members: Bitboard<L::Slot>,
        payload: Payload,
        duration: Duration,
    ) -> Result<(), Full> {
        debug_assert!(members.all(|slot| self.object(slot).zone() == Zone::Battlefield));
        let timestamp = self.zones.next_timestamp;
        self.zones.next_timestamp = timestamp.wrapping_add(1);
        let set = self.effects.sets.lock_in(members)?;
        let pushed = self.effects.entries.push(ContinuousEffect {
            source,
            timestamp,
            duration,
            affected: Affects::Set(set),
            payload,
        });
        if pushed.is_err() {
            // What did not fit is in no index, and holds no place of the table.
            self.effects.sets.release(set);
            self.effects.sets.trim();
            return pushed;
        }
        self.effects.kinds.0 |= Kinds::LAYER;
        self.keyed |= members;
        self.flags.derived_dirty = true;
        Ok(())
    }

    /// The objects the effect on `set` still affects: those it locked in as it began, less
    /// each that has left its zone since. None once the effect has ended.
    #[inline]
    pub fn locked_in(&self, set: LockedIn<L>) -> Bitboard<L::Slot> {
        self.effects.sets.members(set)
    }
}
